package com.mahesh.empleave.department;import com.mahesh.empleave.audit.*;import com.mahesh.empleave.common.dto.*;import com.mahesh.empleave.user.*;import jakarta.validation.constraints.*;import lombok.*;import org.springframework.http.*;import org.springframework.security.access.prepost.*;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/departments") @RequiredArgsConstructor public class DepartmentController{private final DepartmentRepository repo;private final UserRepository users;private final AuditService audit;record Input(@NotBlank @Size(max=100) String name,@Size(max=30) String code){}@GetMapping List<ApiDtos.Department> all(){return repo.findAll().stream().map(ApiDtos::department).toList();}@PostMapping @PreAuthorize("hasRole('ADMIN')") ApiDtos.Department create(Authentication a,@RequestBody @jakarta.validation.Valid Input x){if(repo.existsByName(x.name()))throw new IllegalArgumentException("Department name already exists");var d=repo.save(new Department(x.name(),x.code()));audit.log(users.findByEmail(a.getName()).orElseThrow(),"DEPARTMENT_CREATED","DEPARTMENT",d.getId());return ApiDtos.department(d);}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") ApiDtos.Department update(Authentication a,@PathVariable Long id,@RequestBody @jakarta.validation.Valid Input x){var d=repo.findById(id).orElseThrow();d.update(x.name(),x.code());audit.log(users.findByEmail(a.getName()).orElseThrow(),"DEPARTMENT_UPDATED","DEPARTMENT",id);return ApiDtos.department(d);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(Authentication a,@PathVariable Long id){var d=repo.findById(id).orElseThrow();if(users.existsByDepartment(d))throw new IllegalStateException("Department has assigned employees");repo.delete(d);audit.log(users.findByEmail(a.getName()).orElseThrow(),"DEPARTMENT_DELETED","DEPARTMENT",id);}}
